private boolean createOrUpdatePricingRuleCondition(GUPPricingRuleCondition _ruleCondition, RefRecId _ruleId, GUPRefRecId _conditionAttribute, AttributeValueText _value)
{
    if (_ruleCondition)
    {
        _ruleCondition.ConditionAttribute = _conditionAttribute;
        _ruleCondition.ConditionValue = _value;
        if (!_ruleCondition.validateWrite())
        {
            throw error(strfmt("@GlobalUnifiedPricing:GUPDataEntityInvalidFieldValue", _value, 'LINE'));
        }
        _ruleCondition.update();
    }
    else
    {
        _ruleCondition.RuleId = _ruleId;
        _ruleCondition.ConditionAttribute = _conditionAttribute;
        _ruleCondition.ConditionValue = _value;
        if (!_ruleCondition.validateWrite())
        {
            throw error(strfmt("@GlobalUnifiedPricing:GUPDataEntityInvalidFieldValue", _value, 'LINE'));
        }
        _ruleCondition.insert();
    }
    return true;
}

private GUPPricingAttributeGroup getAndValidateAttributeGroup(Name _name)
{
    GUPPricingAttributeGroup attributeGroup = GUPPricingAttributeGroup::findByName(_name);
    if (!attributeGroup)
    {
        throw error(strfmt("@GlobalUnifiedPricing:GUPDataEntityInvalidRelationError", tablePName(GUPPricingAttributeGroup), this.PriceAttributeGroup));
    }
    return attributeGroup;
}

private void validateAndUpdatePriceTermJournalStatus(GUPPriceTermJournalTrans _trans)
{
    GUPPriceTermJournalTable journal = _trans.gupPriceTermJournalTable();
    if (journal.Status == GUPDisabledEnabled::Enabled)
    {
        boolean ret = _trans.validate();
        if (!ret)
        {
            journal.Status = GUPDisabledEnabled::Disabled;
            journal.update();
        }
    }
}

public void postLoad()
{
    super();
    if (this.PricingRule)
    {
        GUPPricingRule pricingRule = GUPPricingRule::find(this.PricingRule);
        this.PriceAttributeGroup = pricingRule.PriceAttributeGroupName;

        int num = 1;
        str baseFieldName = 'Line';
        GUPPricingRuleCondition ruleCondition;
        GUPPricingAttributeLink attributeLink;
        while select ruleCondition
            where ruleCondition.RuleId == this.PricingRule
            join attributeLink
            order by attributeLink.Priority asc
                where ruleCondition.ConditionAttribute == attributeLink.RecId
        {
            this.setFieldValue(baseFieldName + int2Str(num), ruleCondition.ConditionValue);
            num++;
        }
    }
}

public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret = true;
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(GUPPriceTermJournalTransEntity, GUPPriceTermJournalTrans))
    {
        // set TransDate
        GUPPriceTermJournalTrans trans = _dataSourceCtx.getBuffer();
        trans.TransDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

        if (this.PriceAttributeGroup)
        {
            GUPPricingAttributeGroup attributeGroup = this.getAndValidateAttributeGroup(this.PriceAttributeGroup);

            // insert pricing rule condition
            GUPPricingRule rule = GUPPricingRule::newPricingRule(attributeGroup.Name, GUPPricingRuleExclusionType::Product);
            trans.PricingRule = rule.RecId;

            int num = 1;
            str baseFieldName = 'Line';
            GUPPricingAttributeLink attributeLink;
            ttsbegin;
            while select attributeLink
                order by attributeLink.Priority asc
                where attributeLink.PriceAttributeGroupName == attributeGroup.Name
            {
                this.createOrUpdatePricingRuleCondition(null, rule.RecId, attributeLink.RecId, this.getFieldValue(baseFieldName + int2Str(num)));
                num ++;
            }
            ttscommit;
        }
    }
    ret = super(_entityCtx, _dataSourceCtx);
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(GUPPriceTermJournalTransEntity, GUPPriceTermJournalTrans))
    {
        // validate price term journal
        GUPPriceTermJournalTrans trans = _dataSourceCtx.getBuffer();
        this.validateAndUpdatePriceTermJournalStatus(trans);
    }
    return ret;
}

public boolean updateEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret = true;
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(GUPPriceTermJournalTransEntity, GUPPriceTermJournalTrans))
    {
        GUPPriceTermJournalTrans trans = _dataSourceCtx.getBuffer();
        if (this.PriceAttributeGroup)
        {
            // validate pricing attribute group
            GUPPricingAttributeGroup attributeGroup = this.getAndValidateAttributeGroup(this.PriceAttributeGroup);

            // insert/update pricing rule condition
            GUPPricingRule rule = trans.gupPricingRule();
            if (rule.PriceAttributeGroupName != attributeGroup.Name)
            {
                rule.selectForUpdate(true);
                rule.delete();
                rule = null;
            }

            if (!rule)
            {
                rule = GUPPricingRule::newPricingRule(attributeGroup.Name, GUPPricingRuleExclusionType::Product);
                trans.PricingRule = rule.RecId;
                trans.update();
            }

            int num = 1;
            str baseFieldName = 'Line';
            GUPPricingAttributeLink attributeLink;
            ttsbegin;
            while select attributeLink
                    order by attributeLink.Priority asc
                    where attributeLink.PriceAttributeGroupName == attributeGroup.Name
            {
                GUPPricingRuleCondition ruleCondition = GUPPricingRuleCondition::find(rule.RecId, attributeLink.RecId, true);
                this.createOrUpdatePricingRuleCondition(ruleCondition, rule.RecId, attributeLink.RecId, this.getFieldValue(baseFieldName + int2Str(num)));
                num ++;
            }
            ttscommit;
        }
        else
        {
            trans.clearPricingRule();
        }
    }
    ret = super(_entityCtx, _dataSourceCtx);
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(GUPPriceTermJournalTransEntity, GUPPriceTermJournalTrans))
    {
        // validate price term journal
        GUPPriceTermJournalTrans trans = _dataSourceCtx.getBuffer();
        this.validateAndUpdatePriceTermJournalStatus(trans);
    }
    return ret;
}
